#!/usr/bin/env python3
import argparse
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import os
from pathlib import Path
import shutil
import signal
import sqlite3
import sys
import threading
import time
from inputs import generate, metrics
from board_data import DetailCache, selection
from urllib.parse import urlsplit, parse_qs
from runner import active, attempt, daemon, export_board, initialize, start, stop_daemon
from store import config, connect, local, root, rows


def status(repo):
    with connect(repo) as db:
        return {'daemon_running': active(repo), 'scouts': rows(db, 'SELECT * FROM scouts ORDER BY name'),
                'conversations': rows(db, 'SELECT * FROM conversation_sources ORDER BY agent')}

def serve(repo, port):
    details = DetailCache()
    cached = {'value': {'error': '計測を取得中です'}}
    shutdown = threading.Event()
    def refresh():
        while not shutdown.is_set():
            try:
                cached['value'] = metrics(repo, config(repo), shutdown)
            except Exception as exc:
                cached['value'] = {'error': str(exc)}
            shutdown.wait(30)
    thread = threading.Thread(target=refresh, daemon=True)
    thread.start()
    def stop_server(*_):
        raise SystemExit(0)
    signal.signal(signal.SIGTERM, stop_server)
    class Handler(BaseHTTPRequestHandler):
        def do_GET(self):
            path = urlsplit(self.path)
            if path.path == '/api/metrics':
                try:
                    args = selection(parse_qs(path.query, keep_blank_values=True))
                    result = details.get(repo, config(repo), *args)
                except ValueError as exc:
                    self.send_error(400, str(exc).encode('ascii', 'replace').decode())
                    return
                body = json.dumps(result, ensure_ascii=False).encode()
                content_type = 'application/json; charset=utf-8'
            elif self.path in ('/board-details.js', '/board-insights.js', '/board-scenario.js', '/mermaid.tiny.js'):
                asset = Path(__file__).parent / ('vendor/mermaid.tiny.js' if self.path == '/mermaid.tiny.js' else self.path[1:])
                body = asset.read_bytes()
                content_type = 'text/javascript; charset=utf-8'
            elif self.path == '/':
                body = Path(__file__).with_name('board.html').read_bytes()
                content_type = 'text/html; charset=utf-8'
            elif self.path == '/api/board':
                result = status(repo)
                # Local execution paths/logs are not part of the human board.
                for scout in result['scouts']:
                    scout.pop('input_ref', None)
                result['metrics'] = cached['value']
                body = json.dumps(result, ensure_ascii=False).encode()
                content_type = 'application/json; charset=utf-8'
            else:
                self.send_error(404)
                return
            self.send_response(200)
            self.send_header('Content-Type', content_type)
            self.send_header('Cache-Control', 'no-store')
            self.send_header('X-Content-Type-Options', 'nosniff')
            self.send_header('Content-Security-Policy', "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; frame-ancestors 'none'")
            self.end_headers()
            self.wfile.write(body)
        def log_message(self, *_):
            pass
    server = ThreadingHTTPServer(('127.0.0.1', port), Handler)
    print(f'http://127.0.0.1:{server.server_port}', flush=True)
    try:
        server.serve_forever()
    finally:
        shutdown.set()
        server.server_close()
        thread.join(timeout=35)


